#include <bits/stdc++.h>
using namespace std;
const int INF = 0x7f7f7f7f;
int n,m,s,t,p,c,d,x[505],y[505];
int flow_total, cost_total;
int edge_pointer=1, head[5000005], next_edge[10000010], to_node[10000010], capacity[10000010], cost_edge[10000010];
int dist[5000005], parent[5000005], last_edge[5000005], flow[5000005];
bool in_queue[5000005];

void add_edge(int u, int v, int cap, int cst) {
    next_edge[++edge_pointer] = head[u];
    to_node[edge_pointer] = v;
    capacity[edge_pointer] = cap;
    cost_edge[edge_pointer] = cst;
    head[u] = edge_pointer;
}

bool spfa_algorithm() {
    memset(dist, 0x7f, sizeof(dist));
    memset(in_queue, false, sizeof(in_queue));
    queue<int> q;
    q.push(s);
    in_queue[s] = true;
    dist[s] = 0;
    flow[s] = INT_MAX;
    parent[t] = -1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue[u] = false;
        for (int i = head[u]; i; i = next_edge[i]) {
            if (capacity[i] && dist[to_node[i]] > dist[u] + cost_edge[i]) {
                dist[to_node[i]] = dist[u] + cost_edge[i];
                parent[to_node[i]] = u;
                last_edge[to_node[i]] = i;
                flow[to_node[i]] = min(flow[u], capacity[i]);
                if (!in_queue[to_node[i]]) {
                    in_queue[to_node[i]] = true;
                    q.push(to_node[i]);
                }
            }
        }
    }
    return parent[t] != -1;
}

void compute_mcmf() {
    flow_total = cost_total = 0;
    while (spfa_algorithm()) {
        int current_node = t;
        flow_total += flow[t];
        cost_total += flow[t] * dist[t];
        while (current_node != s) {
            capacity[last_edge[current_node]] -= flow[t];
            capacity[last_edge[current_node] ^ 1] += flow[t];
            current_node = parent[current_node];
        }
    }
}

int node_id(int layer, int node) {
    return layer * n + node;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> p >> c >> d;
    s = 0;
    t = n * 99 + 1;
    for (int i=1, x; i<=p && cin>>x; i++) {
        add_edge(s, node_id(0,x), 1, 0);
        add_edge(node_id(0,x), s, 0, 0);
    }
    for (int i=1; i<=m; i++) {
        cin>>x[i]>>y[i];
    }
    for (int i=0; i<=99; i++) {
        add_edge(node_id(i,1), node_id(i+1,1), INF, 0);
        add_edge(node_id(i+1,1), node_id(i,1), 0, 0);
        for (int j=2; j<=n; j++) {
            add_edge(node_id(i,j), node_id(i+1,j), INF, c);
            add_edge(node_id(i+1,j), node_id(i,j), 0, -c);
        }
        for (int j=1; j<=m; j++) {
            for (int k=1; k<=p; k++) {
                int cst = d*k*k - d*(k-1)*(k-1) + c;
                add_edge(node_id(i,x[j]), node_id(i+1,y[j]), 1, cst);
                add_edge(node_id(i+1,y[j]), node_id(i,x[j]), 0, -cst);
                add_edge(node_id(i,y[j]), node_id(i+1,x[j]), 1, cst);
                add_edge(node_id(i+1,x[j]), node_id(i,y[j]), 0, -cst);
            }
        }
    }
    compute_mcmf();
    cout << cost_total << "\n";
    return 0;
}
